#!/bin/sh
# Prints the commands. Does not run them.
set -eu
PROJECT="${PROJECT:-krayon-ai}"
REGION="${REGION:-asia-south1}"
BUCKET="${BUCKET:-krayon-ai.firebasestorage.app}"
echo "gcloud iam service-accounts create krayon-api --project ${PROJECT}"
echo "gcloud iam service-accounts create krayon-worker --project ${PROJECT}"
echo "gcloud iam service-accounts create krayon-renderer --project ${PROJECT}"
echo "gcloud iam service-accounts create krayon-tasks --project ${PROJECT}"
echo "gcloud projects add-iam-policy-binding ${PROJECT} --member serviceAccount:krayon-api@${PROJECT}.iam.gserviceaccount.com --role roles/datastore.user"
echo "gcloud projects add-iam-policy-binding ${PROJECT} --member serviceAccount:krayon-api@${PROJECT}.iam.gserviceaccount.com --role roles/cloudtasks.enqueuer"
echo "gcloud storage buckets add-iam-policy-binding gs://${BUCKET} --member serviceAccount:krayon-api@${PROJECT}.iam.gserviceaccount.com --role roles/storage.objectViewer"
echo "gcloud iam service-accounts add-iam-policy-binding krayon-tasks@${PROJECT}.iam.gserviceaccount.com --member serviceAccount:krayon-api@${PROJECT}.iam.gserviceaccount.com --role roles/iam.serviceAccountUser --project ${PROJECT}"
echo "gcloud projects add-iam-policy-binding ${PROJECT} --member serviceAccount:krayon-worker@${PROJECT}.iam.gserviceaccount.com --role roles/datastore.user"
echo "gcloud storage buckets add-iam-policy-binding gs://${BUCKET} --member serviceAccount:krayon-worker@${PROJECT}.iam.gserviceaccount.com --role roles/storage.objectAdmin"
echo "gcloud projects add-iam-policy-binding ${PROJECT} --member serviceAccount:krayon-worker@${PROJECT}.iam.gserviceaccount.com --role roles/aiplatform.user"
echo "gcloud projects add-iam-policy-binding ${PROJECT} --member serviceAccount:krayon-worker@${PROJECT}.iam.gserviceaccount.com --role roles/serviceusage.serviceUsageConsumer"
echo "gcloud projects add-iam-policy-binding ${PROJECT} --member serviceAccount:krayon-worker@${PROJECT}.iam.gserviceaccount.com --role roles/cloudtasks.enqueuer"
echo "gcloud iam service-accounts add-iam-policy-binding krayon-tasks@${PROJECT}.iam.gserviceaccount.com --member serviceAccount:krayon-worker@${PROJECT}.iam.gserviceaccount.com --role roles/iam.serviceAccountUser --project ${PROJECT}"
echo "gcloud run services add-iam-policy-binding krayon-renderer --member serviceAccount:krayon-worker@${PROJECT}.iam.gserviceaccount.com --role roles/run.invoker --region ${REGION} --project ${PROJECT}"
echo "gcloud run services add-iam-policy-binding krayon-worker --member serviceAccount:krayon-tasks@${PROJECT}.iam.gserviceaccount.com --role roles/run.invoker --region ${REGION} --project ${PROJECT}"
echo "# krayon-renderer has no extra roles. It returns PNG bytes; the worker writes them."
